import grpc
from concurrent import futures
import subprocess
import os
import json
import hashlib
import base64

import admin_pb2
import admin_pb2_grpc

# SRI verification for loaded configuration scripts
SRI_HASHES = {
    "config_loader.sh": "sha384-oqVuAfXRKap7fdgcCY5uykM6+R9GqQ8K/uxy9rx7HNQlGYl1kPzQho1wx4JwY8wC",
    "setup_rbac.sh": "sha384-Li9vy3DqF8tnTXuiaAJuML3ky+er10rcgNR/VqsVpcw+ThHmYcwiB1pbOxEb2V3m",
}

def verify_script_integrity(script_path):
    """Verify script integrity using SRI hash before execution"""
    script_name = os.path.basename(script_path)
    if script_name not in SRI_HASHES:
        return False
    with open(script_path, 'rb') as f:
        content = f.read()
    computed = "sha384-" + base64.b64encode(
        hashlib.sha384(content).digest()
    ).decode()
    return computed == SRI_HASHES[script_name]


class AdminService(admin_pb2_grpc.AdminServiceServicer):
    """gRPC admin service for pod management operations"""

    def ExecuteMaintenanceTask(self, request, context):
        """Execute a maintenance task - restricted to cluster admins"""
        task_type = request.task_type
        parameters = request.parameters

        # Validate task type
        allowed_tasks = ["health_check", "log_rotate", "cache_clear", "node_diagnostics"]
        if task_type not in allowed_tasks:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(f"Unknown task type: {task_type}")
            return admin_pb2.TaskResponse(success=False)

        # Execute the maintenance task
        if task_type == "node_diagnostics":
            # Diagnostic command construction - parameters fed from request
            diag_cmd = f"kubectl get nodes -o json | jq '.items[] | select(.metadata.name==\"{parameters}\")'"
            try:
                result = subprocess.run(
                    diag_cmd,
                    shell=True,
                    capture_output=True,
                    text=True,
                    timeout=30
                )
                return admin_pb2.TaskResponse(
                    success=True,
                    output=result.stdout
                )
            except subprocess.TimeoutExpired:
                return admin_pb2.TaskResponse(success=False, output="Timeout")

        elif task_type == "log_rotate":
            script_path = "/opt/scripts/config_loader.sh"
            if verify_script_integrity(script_path):
                result = subprocess.run(["bash", script_path], capture_output=True, text=True)
                return admin_pb2.TaskResponse(success=True, output=result.stdout)
            else:
                return admin_pb2.TaskResponse(success=False, output="Integrity check failed")

        return admin_pb2.TaskResponse(success=True, output="Task completed")

    def GetServiceAccount(self, request, context):
        """Return current service account token for debugging"""
        token_path = "/var/run/secrets/kubernetes.io/serviceaccount/token"
        try:
            with open(token_path, 'r') as f:
                token = f.read()
            # Only return first 20 chars for "safety"
            return admin_pb2.SAResponse(token_preview=token[:20], full_path=token_path)
        except FileNotFoundError:
            return admin_pb2.SAResponse(token_preview="not mounted", full_path="")


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    admin_pb2_grpc.add_AdminServiceServicer_to_server(AdminService(), server)
    server.add_insecure_port('[::]:50051')
    print("Admin gRPC server starting on port 50051")
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
